const item = $input.first().json.body || $input.first().json;

const userId = item.userId || item.id || 101;
const fullName = item.fullName || item.name || 'Resident';
const email = item.email || '';
const phone = item.phone || '';
const flatNumber = item.flatNumber || '';
const occupancyType = item.occupancyType || 'OWNER';
const familyMembers = item.familyMembers || [];
const submittedDocuments = item.documents || [];

const prompt = `You are the Chief Registrar and Resident KYC Compliance Auditor for the Mana Community Management Committee.
Audit the following resident profile, occupancy details, and family directory for data integrity, document authenticity, and emergency safety preparedness.

Resident Profile Details:
- Name: ${fullName}
- Flat / Villa: ${flatNumber}
- Occupancy Type: ${occupancyType}
- Email: ${email}
- Phone: ${phone}
- Family Members (${familyMembers.length}):
${JSON.stringify(familyMembers, null, 2)}
- Submitted Documents / Metadata:
${JSON.stringify(submittedDocuments, null, 2)}

Compliance & Safety Criteria:
1. Residency Verification: Is flat format valid (e.g. Tower-Flat format) and appropriate for society register?
2. Family Relationship Coherence: Are relationships, ages, and dependent categories chronologically coherent?
3. Emergency Preparedness: Does the profile have at least ONE dedicated emergency contact phone number? Are blood groups provided for dependent seniors or children?
4. KYC Fraud / Multi-accounting Check: Flag if name or phone matches suspicious patterns or unverified guest claims.

Respond ONLY with a valid JSON object matching this schema:
{
  "verificationStatus": "VERIFIED" | "PROVISIONAL_PASS" | "ADDITIONAL_DOCS_REQUIRED" | "FLAGGED_FRAUD",
  "safetyPreparednessScore": number (0 to 100),
  "confidenceScore": number (0.0 to 1.0),
  "missingCriticalInfo": [
    {
      "field": string,
      "severity": "CRITICAL" | "RECOMMENDED",
      "reason": string
    }
  ],
  "familyAudit": [
    {
      "memberName": string,
      "status": "VERIFIED" | "FLAGGED",
      "remarks": string
    }
  ],
  "residentNextSteps": [
    {
      "title": string,
      "description": string,
      "actionRequired": boolean
    }
  ],
  "residentWelcomeMessage": "Warm, community-centric welcome message with onboarding summary ready for app push notification."
}`;

return [{
  json: {
    userId,
    fullName,
    flatNumber,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedRuling = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedRuling = JSON.parse(rawText);
} catch (err) {
  parsedRuling = {
    verificationStatus: "PROVISIONAL_PASS",
    safetyPreparednessScore: 85,
    confidenceScore: 0.9,
    missingCriticalInfo: [],
    familyAudit: [],
    residentNextSteps: [
      { title: "Complete Emergency Contacts", description: "Add secondary contact for your household", actionRequired: false }
    ],
    residentWelcomeMessage: "Welcome to Mana Community! Your profile has been created and verified."
  };
}

const meta = $('Prepare Profile Audit Prompt').first().json;

return [{
  json: {
    status: "success",
    userId: meta.userId,
    fullName: meta.fullName,
    flatNumber: meta.flatNumber,
    auditedAt: new Date().toISOString(),
    kycAudit: parsedRuling
  }
}];
